import React, {useState,useEffect,useRef} from 'react';
import {createRoot} from 'react-dom/client';
import {LayoutDashboard,Waypoints,Workflow,Plus,Search,ArrowUpRight,ArrowLeft,ArrowRight,ChevronRight,ChevronDown,MoreHorizontal,Sun,Moon,Settings,Trash2,Tags,Download,Upload,X,Check,Copy,FileText,Grid2X2,List,Clock,CheckCheck,RotateCcw,ExternalLink,MoveUp,MoveDown,Expand,Minus,Pause,Play,BookOpen,Layers,SlidersHorizontal,PenLine,Command,GripVertical,FolderOpen,Archive,Info} from 'lucide-react';
import {marked} from 'marked';
import DOMPurify from 'dompurify';
import Board from './board.jsx';
import SocratesMark from './logo.jsx';
import AppProvider from './app-provider.jsx';
import AppSettings from './app-settings.jsx';
import AppStatus from './app-status.jsx';
import ProfileMenu from './profile-menu.jsx';
import {makeSeed,clone,uid,normalizeTag,upsertNote,newMap,saveMap,getMapNotes,getMapTags,markdownForNotes,STORAGE_KEY} from './model.js';
import {downloadNotes,downloadBackup,parseImport} from './transfers.js';
import {getCardColor} from './board-palette.js';
import {getRoutedPath,getRouteLabelPosition} from './board-geometry.js';
import {effectiveLayerValues} from './board-layers.js';
